-- CBRD-26659 Ticket03: distinct values across modeled VOT widths and many attributes.
-- The signed VOT offset maxima are127/32767, not255/65535.
-- One INT + one VARBIT insert overhead28B (32B with INT-width VOT).
-- N91/N92 serialize96/100 and input records124/128 cross BYTE->SHORT.
-- N32731/N32732 serialize32736/32740 and input records32764/32772 cross SHORT->INT.
-- Ordinary demotion shrinks both large rows to one24B stub and a modeled BYTE-width record.
-- SHOW does not expose VOT widths. Width labels are independent serialization models.
-- All12 forced values are profitable and use12 chains. The same unequal DEFAULT
-- values need exactly the six largest chains, leaving smaller values inline.
-- Exact complete attributes and external hex-text MD5s prevent alias/substitution passes.
-- Default JDBC autocommit. Private physical fixtures are separate invocations.

drop table if exists t03_vot;
drop table if exists t03_many_forced;
drop table if exists t03_many_default;
create table t03_vot (id int primary key,payload bit varying);
insert into t03_vot values (1,cast(repeat('71',91) as bit varying)),(2,cast(repeat('82',92) as bit varying)),(3,cast(repeat('93',32731) as bit varying)),(4,cast(repeat('a4',32732) as bit varying));
select id, octet_length(payload) as payload_octets, disk_size(payload) as payload_disk, md5(payload) as payload_md5, case when id=1 and payload=cast(repeat('71',91) as bit varying) then 1 when id=2 and payload=cast(repeat('82',92) as bit varying) then 1 when id=3 and payload=cast(repeat('93',32731) as bit varying) then 1 when id=4 and payload=cast(repeat('a4',32732) as bit varying) then 1 else 0 end as value_ok from t03_vot order by id;
