select id, case when c01=cast(repeat('10',600) as bit varying) and md5(c01)='8c3e99be7586923ec1a86d91f2a4b177' then 1 else 0 end as c01_ok, case when c02=cast(repeat('11',608) as bit varying) and md5(c02)='3bd39efcb9422b5ffdf36ecbc04c7956' then 1 else 0 end as c02_ok, case when c03=cast(repeat('12',616) as bit varying) and md5(c03)='306114e8abcde555b204edfc6a6862f0' then 1 else 0 end as c03_ok, case when c04=cast(repeat('13',624) as bit varying) and md5(c04)='eec60747fb07858762a9afb158d6e9cd' then 1 else 0 end as c04_ok, case when c05=cast(repeat('14',632) as bit varying) and md5(c05)='b6a630e57cd20f6cc31558b454449021' then 1 else 0 end as c05_ok, case when c06=cast(repeat('15',640) as bit varying) and md5(c06)='f00460ccb338451b22439ef83ac7699d' then 1 else 0 end as c06_ok, case when c07=cast(repeat('16',648) as bit varying) and md5(c07)='110a95df38cbd55b01a54b13228cee9f' then 1 else 0 end as c07_ok, case when c08=cast(repeat('17',656) as bit varying) and md5(c08)='389c2376c7c7cd35027c1e25ac5057c0' then 1 else 0 end as c08_ok, case when c09=cast(repeat('18',664) as bit varying) and md5(c09)='c4fda1e465cc847ce72348f4e7341db0' then 1 else 0 end as c09_ok, case when c10=cast(repeat('19',672) as bit varying) and md5(c10)='4cfc5cd3d1dd6ed9ac1948ea4c9698b2' then 1 else 0 end as c10_ok, case when c11=cast(repeat('1a',680) as bit varying) and md5(c11)='7a81d012a89ff3c8906984db438bfde8' then 1 else 0 end as c11_ok, case when c12=cast(repeat('1b',688) as bit varying) and md5(c12)='fe3e6470620784d5d4ae6ee666819d18' then 1 else 0 end as c12_ok, octet_length(c01)+octet_length(c02)+octet_length(c03)+octet_length(c04)+octet_length(c05)+octet_length(c06)+octet_length(c07)+octet_length(c08)+octet_length(c09)+octet_length(c10)+octet_length(c11)+octet_length(c12) as total_octets, disk_size(c01)+disk_size(c02)+disk_size(c03)+disk_size(c04)+disk_size(c05)+disk_size(c06)+disk_size(c07)+disk_size(c08)+disk_size(c09)+disk_size(c10)+disk_size(c11)+disk_size(c12) as total_serialized from t03